contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= depositAmount);

        uint256 balanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cEtherBefore = address(c).balance;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 balanceAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cEtherAfter = address(c).balance;

        assert(balanceAfter == 0 && cEtherAfter <= cEtherBefore);
    }

    receive() external payable {}
}

