// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint256 balanceBefore;
        try c.balances(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        uint256 cEtherBefore = address(c).balance;
        try c.withdraw() {} catch { return; }
        uint256 balanceAfter;
        try c.balances(address(this)) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        uint256 cEtherAfter = address(c).balance;
        assertTrue(balanceAfter == 0 && cEtherAfter <= cEtherBefore);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
